def sum_of_multiples(limit, multiples):
    """
    Return the sum of all unique multiples of the given factors that are less than limit.

    Parameters:
    - limit (int): the upper bound (exclusive) for multiples
    - multiples (list[int]): sorted, unique list of non-negative integer factors

    Notes:
    - Factors that are 0 are ignored (no valid multiples).
    """
    if limit <= 0 or not multiples:
        return 0

    seen = set()
    for m in multiples:
        if m == 0:
            continue
        for val in range(m, limit, m):
            seen.add(val)

    return sum(seen)
